/**
 * Tactical
 * Wound Resolver
 *
 * Determines whether an attack causes a Wound.
 */

/**
 * Resolve Wound generation from a single attack.
 *
 * @param {object} options
 * @param {number} options.criticalPoints
 * Natural 12s generated by the successful attack roll.
 *
 * @param {number} options.healthDamage
 * Damage that reached Health or Hull after Toughness and Integrity.
 *
 * @param {number} options.maxHealth
 * Target's maximum Health or Hull.
 *
 * @param {number} options.currentWounds
 * Target's current Wounds Taken.
 *
 * @param {number} options.maxWounds
 * Target's maximum Wounds.
 *
 * @param {number} options.maxWoundsPerAttack
 * Maximum Wounds this attack may inflict.
 *
 * @returns {object}
 */
export function resolveTacticalWound({
  criticalPoints = 0,
  healthDamage = 0,
  maxHealth = 0,
  currentWounds = 0,
  maxWounds = 0,
  maxWoundsPerAttack = 1
} = {}) {

  const cp = Math.max(
    0,
    Number(criticalPoints) || 0
  );

  const directDamage = Math.max(
    0,
    Number(healthDamage) || 0
  );

  const targetMaxHealth = Math.max(
    0,
    Number(maxHealth) || 0
  );

  const woundsBefore = Math.max(
    0,
    Number(currentWounds) || 0
  );

  const woundMaximum = Math.max(
    0,
    Number(maxWounds) || 0
  );

  const attackWoundCap = Math.max(
    0,
    Number(maxWoundsPerAttack) || 0
  );

  /* -------------------------------------------- */
  /*  Wound Conditions                            */
  /* -------------------------------------------- */

  const criticalWound =
    cp >= 2 &&
    directDamage > 0;

  const massiveDamageThreshold =
    targetMaxHealth > 0
      ? targetMaxHealth * 0.5
      : Infinity;

  const massiveDamageWound =
    directDamage >= massiveDamageThreshold;

  const woundTriggered =
    criticalWound ||
    massiveDamageWound;

  /* -------------------------------------------- */
  /*  Wounds Applied                              */
  /* -------------------------------------------- */

  const remainingWoundCapacity = Math.max(
    0,
    woundMaximum - woundsBefore
  );

  const woundsApplied = woundTriggered
    ? Math.min(
        1,
        attackWoundCap,
        remainingWoundCapacity
      )
    : 0;

  const woundsAfter =
    woundsBefore + woundsApplied;

  /* -------------------------------------------- */
  /*  Result                                      */
  /* -------------------------------------------- */

  return {
    criticalPoints: cp,
    healthDamage: directDamage,
    maxHealth: targetMaxHealth,

    triggers: {
      critical: criticalWound,
      massiveDamage: massiveDamageWound
    },

    woundTriggered,

    wounds: {
      before: woundsBefore,
      applied: woundsApplied,
      after: woundsAfter,
      max: woundMaximum
    },

    dead:
      woundMaximum > 0 &&
      woundsAfter >= woundMaximum
  };
}
